		Environment: anchor.Environment, ControllerSlots: controllerSlots, AnchorExpiresAt: fixture.anchor.ExpiresAt(),
		TrustRoots: fixture.authority.roots, Delegations: []trust.VerifiedDelegation{delegation},
		TrustPolicy: fixture.policy, VerificationNow: client.currentTime,
	}
	ledger, err := NewLedger(client, config)
	if err != nil {
		t.Fatalf("NewLedger(): %v", err)
	}
	profile := LaunchProfile{
		Slot: row.Slot, CompartmentOCID: row.CompartmentOCID, AvailabilityDomain: row.AvailabilityDomain,
		FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
		NetworkSecurityGroupOCIDs: slices.Clone(row.NetworkSecurityGroupOCIDs), Shape: row.Shape,
	}
	launchDigest, err := launchProfileDigest(profile)
	if err != nil {
		t.Fatal(err)
	}
	rowDigest, err := FounderPeerRowDigest(row)
	if err != nil {
		t.Fatal(err)
	}
	if planDigestPin == "" {
		planDigestPin = plan.Digest()
	}
	if rowDigestPin == "" {
		rowDigestPin = rowDigest
	}
	intent := Intent{
		SchemaVersion: 1, Mode: IntentModeManaged, DeploymentID: anchor.DeploymentID,
		Cell: string(anchor.Cell), Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
		Attempt: 1, Generation: 1, ManifestDigest: row.ManifestSHA256,
		ReleaseReceiptDigest: digestBytes([]byte("release")), RegionIntentGeneration: anchor.InitialRegionIntentGeneration,
		ImageOCID: row.ImageOCID, RegionIntentDigest: anchor.InitialRegionIntentSHA256,
		LaunchRequestDigest: launchDigest, FounderPlanSHA256: planDigestPin, PeerRowDigest: rowDigestPin,
		CreateKey: "create-" + row.Slot, RetryToken: "retry-" + row.Slot, CreatedAt: fixture.now,
		OCIRegion: "sa-saopaulo-1", CompartmentOCID: row.CompartmentOCID,
		AvailabilityDomain: row.AvailabilityDomain, FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
		NetworkSecurityGroupIDs: slices.Clone(row.NetworkSecurityGroupOCIDs), Shape: row.Shape, Node: row.Slot,
	}
	scope := BootstrapScope{DeploymentID: anchor.DeploymentID, Cell: string(anchor.Cell), Slot: row.Slot}
	intentPayload, err := trust.EncodePayload(intent)
	if err != nil {
		t.Fatal(err)
	}
	intentEnvelope, err := trust.Sign(intentPayload, trust.Scope{
		Domain: domainBootstrapIntent, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
	}, fixture.now, fixture.now.Add(23*time.Hour), fixture.authority.peerPrivate)
	if err != nil {
		t.Fatal(err)
	}
	intentWire, err := trust.EncodeEnvelope(intentEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	head := SlotHead{
		SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: anchor.Environment,
		Role: roleController, Slot: row.Slot, Attempt: 1, Generation: 1, IntentDigest: digestBytes(intentWire),
	}
	headPayload, err := trust.EncodePayload(head)
	if err != nil {
		t.Fatal(err)
	}
	headEnvelope, err := trust.Sign(headPayload, trust.Scope{
		Domain: domainBootstrapHead, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: anchor.Environment, Role: roleController, Slot: row.Slot,
	}, fixture.now, fixture.now.Add(23*time.Hour), fixture.authority.peerPrivate)
	if err != nil {
		t.Fatal(err)
	}
	headWire, err := trust.EncodeEnvelope(headEnvelope)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := ledger.ReserveSlot(t.Context(), scope, intentWire, headWire); err != nil {
		t.Fatalf("ReserveSlot(): %v", err)
	}
	launch, err := ledger.ReadForLaunch(t.Context(), scope)
	if err != nil {
		t.Fatalf("ReadForLaunch(): %v", err)
	}
	return launch
}

func (ledger *Ledger) RecordManagedPeerCandidate(ctx context.Context, scope BootstrapScope,
	candidateWire []byte, signProgress ManagedPeerProgressSigner, refresh ManagedPeerRecoveryRefresh,
) error {
	if err := ledger.validateAnchorScope(scope); err != nil {
		return err
	}
	baseline, err := ledger.readSlotForManagedPeerRecovery(ctx, scope)
	if err != nil {
		return err
	}
	if baseline.Intent.Mode != IntentModeManaged || baseline.Intent.SchemaVersion != 1 || baseline.Head.SchemaVersion != 1 {
		return ErrFounderPlanRequired
	}
	candidate, candidateEnvelope, err := ledger.decodeManagedPeerCandidate(scope, candidateWire, true)
	if err != nil {
		return err
	}
	if err := validateManagedPeerCandidateForIntent(candidate, baseline.Intent, baseline.IntentRecord.SHA256,
		baseline.Intent.FounderPlanSHA256, baseline.Intent.PeerRowDigest, baseline.Intent.ManifestDigest); err != nil {
		return err
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return err
	}
	peer, err := ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if peer.recovery.phase != ManagedPeerRecoveryClean && peer.recovery.phase != ManagedPeerRecoveryManifestOnly &&
		peer.recovery.phase != ManagedPeerRecoveryCandidateOnly {
		return ErrRecordAuthorization
	}
	if peer.recovery.phase == ManagedPeerRecoveryCandidateOnly {
		stored := peer.recovery.state.CandidateRecord
		if stored == nil || !bytes.Equal(stored.Bytes, candidateWire) {
			return ErrImmutableConflict
		}
		if progressRecord := peer.recovery.state.ProgressRecord; progressRecord != nil {
			return nil
		}
	}
	if !peer.recovery.AuthorizationTime().Before(candidateEnvelope.ExpiresAt) {
		return fmt.Errorf("%w: candidate signature is not current at the refreshed recovery clock", ErrRecordAuthorization)
	}
	candidateRecord, err := ledger.createOrRead(ctx, scope, baseline.Head.Attempt, ledgerCandidate, candidateWire)
	if err != nil {
		return err
	}
	if err := validateStoredInterval(candidateRecord, candidateEnvelope); err != nil {
		return err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(candidateRecord); err != nil {
		return err
	}
	baseline.Candidate = &candidate
	baseline.CandidateRecord = &candidateRecord
	_, progress, err := ledger.readManagedPeerProgress(ctx, scope, baseline.Head.Attempt, false)
	if err == nil {
		if progress.CandidateDigest != candidateRecord.SHA256 {
			return ErrImmutableConflict
		}
		return nil
	}
	if !errors.Is(err, ErrRecordMissing) {
		return err
	}
	peer, err = ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if peer.recovery.phase != ManagedPeerRecoveryCandidateOnly || peer.recovery.state.CandidateRecord == nil ||
		peer.recovery.state.CandidateRecord.SHA256 != candidateRecord.SHA256 {
		return ErrRecordAuthorization
	}
	progress = ManagedPeerProgress{
		SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
		Environment: ledger.config.Environment, Role: roleController, Slot: scope.Slot,
		Attempt: baseline.Head.Attempt, Generation: baseline.Head.Generation, Sequence: 1,
		CandidateDigest: candidateRecord.SHA256, Phase: ManagedPeerProgressCandidate,
	}
	progressWire, progressEnvelope, err := ledger.signManagedPeerProgress(peer, progress, signProgress)
	if err != nil {
		return err
	}
	peer, err = ledger.refreshManagedPeer(ctx, scope, baseline, refresh)
	if err != nil {
		return err
	}
	if err := ensureCandidateAndProgressBaseline(peer, candidateRecord.SHA256, 0, ""); err != nil {
		return err
	}
	effectCtx, cancel, err := managedPeerEffectContext(ctx, peer, time.Time{}, progressEnvelope.ExpiresAt)
	if err != nil {
		return err
	}
	defer cancel()
	_, _, err = ledger.writeManagedPeerProgress(effectCtx, scope, baseline.Head.Attempt, "", progress, progressWire, progressEnvelope)
	return err
}

func (ledger *Ledger) signManagedPeerProgress(peer VerifiedFounderPeer, progress ManagedPeerProgress,
	signer ManagedPeerProgressSigner,
) ([]byte, trust.Envelope, error) {
	if signer == nil || !peer.IsVerified() || peer.recovery == nil || !peer.recovery.verified {
		return nil, trust.Envelope{}, ErrRecordAuthorization
	}
	issuedAt := peer.recovery.serverDate.UTC()
	expiresAt := earlierTime(issuedAt.Add(managedPeerProgressLifetime), peer.EffectDeadline())
	if !ledger.config.AnchorExpiresAt.IsZero() {
		expiresAt = earlierTime(expiresAt, ledger.config.AnchorExpiresAt)
	}
	if !issuedAt.Before(expiresAt) {
		return nil, trust.Envelope{}, ErrFounderPlanExpired
	}
	wire, err := signer(progress, issuedAt, expiresAt)
	if err != nil {
		return nil, trust.Envelope{}, err
	}
	envelope, payload, err := ledger.signedPayload(wire, peer.recovery.scope, domainBootstrapProgress, true)
	if err != nil {
		return nil, trust.Envelope{}, err
	}
	var signedProgress ManagedPeerProgress
	if err := decodeCanonicalPayload(payload, &signedProgress); err != nil || !sameManagedPeerProgress(progress, signedProgress) ||
		!envelope.IssuedAt.Equal(issuedAt) || !envelope.ExpiresAt.Equal(expiresAt) {
		return nil, trust.Envelope{}, fmt.Errorf("%w: progress signer returned bytes outside the requested scope, sequence, or time bounds", ErrRecordAuthorization)
	}
	if _, _, err := ledger.decodeManagedPeerProgress(peer.recovery.scope, wire, true); err != nil {
		return nil, trust.Envelope{}, err
	}
	return bytes.Clone(wire), envelope, nil
}

func sameManagedPeerProgress(left, right ManagedPeerProgress) bool {
	return left.SchemaVersion == right.SchemaVersion && left.DeploymentID == right.DeploymentID &&
		left.Cell == right.Cell && left.Environment == right.Environment && left.Role == right.Role &&
		left.Slot == right.Slot && left.Attempt == right.Attempt && left.Generation == right.Generation &&
		left.Sequence == right.Sequence && left.CandidateDigest == right.CandidateDigest && left.Phase == right.Phase &&
		left.PendingProofKind == right.PendingProofKind && left.PendingProofDigest == right.PendingProofDigest &&
		bytes.Equal(left.PendingProofWire, right.PendingProofWire)
}

func ensureCandidateAndProgressBaseline(peer VerifiedFounderPeer, candidateDigest string,
	sequence uint64, etag string,
) error {
	if !peer.IsVerified() || peer.recovery == nil || !peer.recovery.verified ||
		peer.recovery.state.CandidateRecord == nil || peer.recovery.state.CandidateRecord.SHA256 != candidateDigest {
		return ErrRecordAuthorization
	}
	progressRecord := peer.recovery.state.ProgressRecord
	if sequence == 0 {
		if progressRecord != nil {
			return ErrSlotHeadConflict
		}
		return nil
	}
	if progressRecord == nil || progressRecord.ETag != etag || peer.recovery.state.Progress == nil ||
		peer.recovery.state.Progress.Sequence != sequence || peer.recovery.state.Progress.CandidateDigest != candidateDigest {
		return ErrSlotHeadConflict
	}
	return nil
}

func (ledger *Ledger) stageManagedPeerProof(ctx context.Context, scope BootstrapScope, attempt uint64,
	candidateDigest string, phase ManagedPeerProgressPhase, proofKind string, proofWire []byte,
	signer ManagedPeerProgressSigner, refresh func() (VerifiedFounderPeer, error),
) error {
	if !validDigest(candidateDigest) || proofKind != "receipt" && proofKind != "result" ||
		phase != ManagedPeerProgressReceipt && phase != ManagedPeerProgressResult ||
		phase == ManagedPeerProgressReceipt && proofKind != "receipt" ||
		phase == ManagedPeerProgressResult && proofKind != "result" || len(proofWire) == 0 || len(proofWire) > ledger.maxRecord {
		return ErrInvalidRecord
	}
	proofDigest := objectDigest(proofWire)
	for {
		peer, err := refresh()
		if err != nil {
			return err
		}
		state := peer.recovery.state
		if state.CandidateRecord == nil || state.CandidateRecord.SHA256 != candidateDigest {
			return ErrRecordAuthorization
		}
		prior := state.Progress
		priorRecord := state.ProgressRecord
		if prior != nil && prior.Phase == phase && prior.PendingProofKind == proofKind &&
			prior.PendingProofDigest == proofDigest && bytes.Equal(prior.PendingProofWire, proofWire) {
			return nil
		}
		if prior == nil {
			candidateProgress := ManagedPeerProgress{
				SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
				Environment: ledger.config.Environment, Role: roleController, Slot: scope.Slot,
				Attempt: attempt, Generation: state.Intent.Generation, Sequence: 1,
				CandidateDigest: candidateDigest, Phase: ManagedPeerProgressCandidate,
			}
			candidateWire, candidateEnvelope, signErr := ledger.signManagedPeerProgress(peer, candidateProgress, signer)
			if signErr != nil {
				return signErr
			}
			fresh, refreshErr := refresh()
			if refreshErr != nil {
				return refreshErr
			}
			if err := ensureCandidateAndProgressBaseline(fresh, candidateDigest, 0, ""); err != nil {
				if errors.Is(err, ErrSlotHeadConflict) {
					continue
				}
				return err
			}
			effectCtx, cancel, effectErr := managedPeerEffectContext(ctx, fresh, time.Time{}, candidateEnvelope.ExpiresAt)
			if effectErr != nil {
				return effectErr
			}
			_, _, writeErr := ledger.writeManagedPeerProgress(effectCtx, scope, attempt, "", candidateProgress,
				candidateWire, candidateEnvelope)
			cancel()
			if writeErr != nil {
				if errors.Is(writeErr, ErrSlotHeadConflict) {
					continue
				}
				return writeErr
			}
			continue
		}
		if priorRecord == nil || prior.CandidateDigest != candidateDigest || prior.Attempt != attempt ||
			prior.Generation != state.Intent.Generation {
			return ErrRecordAuthorization
		}
		priorRank := managedPeerProgressRank(prior.Phase)
		nextRank := managedPeerProgressRank(phase)
		if priorRank == 0 || nextRank == 0 || nextRank > priorRank+1 || nextRank < priorRank && !state.quarantined {
			return ErrRecordAuthorization
		}
		if !state.quarantined && prior.Phase == phase {
			return ErrImmutableConflict
		}
		if prior.Sequence == ^uint64(0) {
			return fmt.Errorf("%w: managed-peer progress sequence is exhausted", ErrInvalidRecord)
		}
		progress := ManagedPeerProgress{
			SchemaVersion: 1, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: ledger.config.Environment, Role: roleController, Slot: scope.Slot,
			Attempt: attempt, Generation: state.Intent.Generation, Sequence: prior.Sequence + 1,
			CandidateDigest: candidateDigest, Phase: phase, PendingProofKind: proofKind,
			PendingProofDigest: proofDigest, PendingProofWire: bytes.Clone(proofWire),
		}
		progressWire, progressEnvelope, signErr := ledger.signManagedPeerProgress(peer, progress, signer)
		if signErr != nil {
			return signErr
		}
		fresh, refreshErr := refresh()
		if refreshErr != nil {
			return refreshErr
		}
		if err := ensureCandidateAndProgressBaseline(fresh, candidateDigest, prior.Sequence, priorRecord.ETag); err != nil {
			if errors.Is(err, ErrSlotHeadConflict) {
				continue
			}
			return err
		}
		effectCtx, cancel, effectErr := managedPeerEffectContext(ctx, fresh, time.Time{}, progressEnvelope.ExpiresAt)
		if effectErr != nil {
			return effectErr
		}
		_, _, writeErr := ledger.writeManagedPeerProgress(effectCtx, scope, attempt, priorRecord.ETag,
			progress, progressWire, progressEnvelope)
		cancel()
		if errors.Is(writeErr, ErrSlotHeadConflict) {
			continue
		}
		return writeErr
	}
}

func managedPeerProgressRank(phase ManagedPeerProgressPhase) int {
	switch phase {
	case ManagedPeerProgressCandidate:
		return 1
	case ManagedPeerProgressReceipt:
		return 2
	case ManagedPeerProgressResult:
		return 3
	default:
		return 0
	}
}

func (ledger *Ledger) readManagedPeerProgress(ctx context.Context, scope BootstrapScope, attempt uint64,
	current bool,
) (StoredRecord, ManagedPeerProgress, error) {
	if err := validateLedgerScope(scope); err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	record, err := ledger.readObject(ctx, ledger.config.HeadBucket, ledger.progressObjectName(scope, attempt))
	if err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	progress, envelope, err := ledger.decodeManagedPeerProgress(scope, record.Bytes, current)
	if err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	if progress.Attempt != attempt {
		return StoredRecord{}, ManagedPeerProgress{}, ErrRecordAuthorization
	}
	_ = envelope // The recovery reader classifies stale progress as quarantined.
	return record, progress, nil
}

func (ledger *Ledger) writeManagedPeerProgress(ctx context.Context, scope BootstrapScope, attempt uint64,
	ifMatch string, expected ManagedPeerProgress, body []byte, envelope trust.Envelope,
) (StoredRecord, ManagedPeerProgress, error) {
	if ledger.readOnly {
		return StoredRecord{}, ManagedPeerProgress{}, ErrRecordAuthorization
	}
	decoded, _, err := ledger.decodeManagedPeerProgress(scope, body, true)
	if err != nil || !sameManagedPeerProgress(decoded, expected) {
		return StoredRecord{}, ManagedPeerProgress{}, ErrRecordAuthorization
	}
	if err := ledger.validateCurrentAuthority(ctx); err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	objectName := ledger.progressObjectName(scope, attempt)
	length := int64(len(body))
	digest := sha256.Sum256(body)
	digestHeader := base64.StdEncoding.EncodeToString(digest[:])
	ifNoneMatch := "*"
	request := objectstorage.PutObjectRequest{
		NamespaceName: new(ledger.config.Namespace), BucketName: new(ledger.config.HeadBucket),
		ObjectName: new(objectName), PutObjectBody: io.NopCloser(bytes.NewReader(body)),
		ContentLength: &length, ContentType: new("application/json"), OpcSseKmsKeyId: new(ledger.config.HeadKMSKeyID),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256, OpcContentSha256: &digestHeader,
	}
	if ifMatch == "" {
		request.IfNoneMatch = &ifNoneMatch
	} else {
		request.IfMatch = &ifMatch
	}
	if err := ctx.Err(); err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	response, putErr, putAttempted := ledger.putObjectAfterTimestampBoundary(ctx, request, envelope)
	if putErr != nil && (!putAttempted || !shouldReadAfterPutError(putErr)) {
		return StoredRecord{}, ManagedPeerProgress{}, fmt.Errorf("write managed-peer progress CAS: %w", putErr)
	}
	stored, readErr := ledger.readObject(ctx, ledger.config.HeadBucket, objectName)
	if readErr != nil {
		return StoredRecord{}, ManagedPeerProgress{}, fmt.Errorf("%w: managed-peer progress write: %v; exact-key read: %w", ErrOutcomeUnknown, putErr, readErr)
	}
	progress, storedEnvelope, err := ledger.decodeManagedPeerProgress(scope, stored.Bytes, false)
	if err != nil || !sameManagedPeerProgress(progress, expected) || !bytes.Equal(stored.Bytes, body) {
		return StoredRecord{}, ManagedPeerProgress{}, ErrSlotHeadConflict
	}
	if putErr == nil && response.ETag != nil && *response.ETag != "" && stored.ETag != *response.ETag {
		return StoredRecord{}, ManagedPeerProgress{}, ErrSlotHeadConflict
	}
	if err := validateStoredInterval(stored, storedEnvelope); err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	if err := ledger.validateStoredBeforeAnchorExpiry(stored); err != nil {
		return StoredRecord{}, ManagedPeerProgress{}, err
	}
	stored.Created = ifMatch == "" && putErr == nil
	return stored, progress, nil

func (ledger *Ledger) readManagedPeerState(ctx context.Context, scope BootstrapScope, state SlotState,
	allowQuarantine bool,
) (SlotState, error) {
	if !allowQuarantine && state.quarantined {
		return SlotState{}, ErrRecordAuthorization
	}
	manifestRecord, manifestErr := ledger.read(ctx, scope, state.Head.Attempt, ledgerManifest)
	if manifestErr != nil && !errors.Is(manifestErr, ErrRecordMissing) {
		return SlotState{}, manifestErr
	}
	if manifestErr == nil {
		manifest, envelope, err := ledger.verifyHistoricalIntentManifest(ctx, scope, state.Intent, manifestRecord.Bytes)
		if err != nil || manifestRecord.SHA256 != state.Intent.ManifestDigest {
			return SlotState{}, ErrRecordAuthorization
		}
		manifestValue := manifest.Manifest()
		state.Manifest = &manifestValue
		state.ManifestRecord = &manifestRecord
		if err := validateStoredInterval(manifestRecord, envelope); err != nil ||
			ledger.validateStoredBeforeAnchorExpiry(manifestRecord) != nil {
			state.quarantined = true
		}
	}

	candidateRecord, candidateErr := ledger.read(ctx, scope, state.Head.Attempt, ledgerCandidate)
	if candidateErr != nil && !errors.Is(candidateErr, ErrRecordMissing) {
		return SlotState{}, candidateErr
	}
	if candidateErr == nil {
		candidate, _, err := ledger.decodeManagedPeerCandidate(scope, candidateRecord.Bytes, false)
		if err != nil || validateManagedPeerCandidateForIntent(candidate, state.Intent, state.IntentRecord.SHA256,
			state.Intent.FounderPlanSHA256, state.Intent.PeerRowDigest, state.Intent.ManifestDigest) != nil {
			return SlotState{}, ErrRecordAuthorization
		}
		state.Candidate, state.CandidateRecord = &candidate, &candidateRecord
		if state.Head.CandidateDigest != "" && state.Head.CandidateDigest != candidateRecord.SHA256 {
			return SlotState{}, ErrRecordAuthorization
		}
	} else if state.Head.CandidateDigest != "" {
		return SlotState{}, fmt.Errorf("%w: HEAD candidate digest has no fixed candidate object", ErrRecordAuthorization)
	}

	progressRecord, progress, progressErr := ledger.readManagedPeerProgress(ctx, scope, state.Head.Attempt, false)
	if progressErr != nil && !errors.Is(progressErr, ErrRecordMissing) {
		return SlotState{}, progressErr
	}
	if progressErr == nil {
		if state.CandidateRecord == nil || progress.CandidateDigest != state.CandidateRecord.SHA256 ||
			progress.Generation != state.Intent.Generation {
			return SlotState{}, fmt.Errorf("%w: progress does not bind the fixed candidate and active intent", ErrRecordAuthorization)
		}
		state.Progress, state.ProgressRecord = &progress, &progressRecord
		progressEnvelope, err := trust.DecodeEnvelope(progressRecord.Bytes)
		completedResult := state.Head.ResultDigest != "" && progress.Phase == ManagedPeerProgressResult &&
			progress.PendingProofDigest == state.Head.ResultDigest
		if err != nil || validateStoredInterval(progressRecord, progressEnvelope) != nil ||
			!ledger.now().Before(progressEnvelope.ExpiresAt) && !completedResult {
			state.quarantined = true
		}
	}
	if state.Head.ResultDigest != "" && (state.CandidateRecord == nil || progressErr != nil) {
		return SlotState{}, fmt.Errorf("%w: completed HEAD is missing its signed candidate or progress proof", ErrRecordAuthorization)
	}

	var resultDigest string
	var resultWire []byte
	if progressErr == nil && progress.Phase == ManagedPeerProgressResult &&
		(state.Head.ResultDigest == "" || progress.PendingProofDigest != state.Head.ResultDigest) {
		resultDigest = progress.PendingProofDigest
		resultWire = bytes.Clone(progress.PendingProofWire)
		if state.Head.ResultDigest != "" {
			// The signed progress CAS proposes a replacement proof set for a
			// completed HEAD. It remains quarantined until fresh authority
			// reobserves the pinned instance and CASes the matching HEAD.
			state.quarantined = true
		}
	} else if state.Head.ResultDigest != "" {
		resultDigest = state.Head.ResultDigest
	}
	if resultDigest != "" {
		resultRecord, err := ledger.readContent(ctx, scope, state.Head.Attempt, ledgerResult, resultDigest)
		if err != nil && len(resultWire) == 0 {
			return SlotState{}, fmt.Errorf("read content-addressed managed result: %w", err)
		}
		resultStored := err == nil
		if err == nil && resultRecord.SHA256 != resultDigest {
			return SlotState{}, ErrRecordAuthorization
		}
		if err != nil {
			resultRecord = StoredRecord{Bytes: resultWire, SHA256: resultDigest}
		}
		resultEnvelope, envelopeErr := trust.DecodeEnvelope(resultRecord.Bytes)
		result, decodeErr := ledger.decodeResult(scope, resultRecord.Bytes, false)
		if envelopeErr != nil || decodeErr != nil || validateResultForIntent(result, state.Intent, state.IntentRecord.SHA256) != nil ||
			result.Mode != IntentModeManaged || result.SeedReceiptDigest != "" {
			return SlotState{}, fmt.Errorf("%w: content-addressed result does not match the active intent", ErrRecordAuthorization)
		}
		if resultStored {
			state.ResultRecord = &resultRecord
			if validateStoredInterval(resultRecord, resultEnvelope) != nil || ledger.validateStoredBeforeAnchorExpiry(resultRecord) != nil ||
				validateResultClock(result, resultRecord, ledger.config.TrustPolicy.ClockSkew) != nil {
				state.quarantined = true
			}
		} else if state.Head.ResultDigest != "" {
			state.quarantined = true
		}
		state.Result = &result
		if state.Head.ResultDigest != "" && state.Head.ResultDigest != resultDigest {
			state.quarantined = true
		}
	}

	var receiptDigest string
	var receiptWire []byte
	if state.Result != nil {
		receiptDigest = state.Result.PeerReceiptDigest
		if progressErr == nil && progress.Phase == ManagedPeerProgressReceipt &&
			progress.PendingProofDigest != receiptDigest {
			// A quarantined repair may stage a fresh receipt before its matching
			// replacement result. Do not pair that receipt with the old HEAD
			// result while recovery is in progress.
			state.Result = nil
			state.ResultRecord = nil
			state.quarantined = true
			receiptDigest = progress.PendingProofDigest
			receiptWire = bytes.Clone(progress.PendingProofWire)
		}
	} else if progressErr == nil && progress.Phase == ManagedPeerProgressReceipt {
		receiptDigest = progress.PendingProofDigest
		receiptWire = bytes.Clone(progress.PendingProofWire)
	}
	if receiptDigest != "" {
		receiptRecord, err := ledger.readContent(ctx, scope, state.Head.Attempt, ledgerPeerReceipt, receiptDigest)
		if err != nil && len(receiptWire) == 0 {
			return SlotState{}, fmt.Errorf("read content-addressed managed receipt: %w", err)
		}
		receiptStored := err == nil
		if err == nil && receiptRecord.SHA256 != receiptDigest {
			return SlotState{}, ErrRecordAuthorization
		}
		if err != nil {
			receiptRecord = StoredRecord{Bytes: receiptWire, SHA256: receiptDigest}
		}
		receiptEnvelope, err := trust.DecodeEnvelope(receiptRecord.Bytes)
		if err != nil {
			return SlotState{}, ErrRecordAuthorization
		}
		receipt, err := ReceiptPayload(receiptEnvelope.Payload)
		if err != nil || validatePeerReceiptForIntent(receipt, state.Intent, state.IntentRecord.SHA256) != nil {
			return SlotState{}, ErrRecordAuthorization
		}
		if state.Manifest != nil {
			facts, factsErr := instanceFactsFromReceipt(receipt, *state.Manifest)
			if factsErr != nil {
				return SlotState{}, ErrRecordAuthorization
			}
			historicalManifest, _, manifestErr := ledger.verifyHistoricalIntentManifest(ctx, scope, state.Intent, state.ManifestRecord.Bytes)
			if manifestErr != nil {
				return SlotState{}, ErrRecordAuthorization
			}
			if _, err := VerifyHistoricalPeerReceipt(receiptEnvelope, historicalManifest, facts, ledger.config.TrustPolicy); err != nil {
				return SlotState{}, ErrRecordAuthorization
			}
		}
		state.PeerReceipt = &receipt
		if receiptStored {
			state.PeerReceiptRecord = &receiptRecord
			if validateStoredInterval(receiptRecord, receiptEnvelope) != nil || ledger.validateStoredBeforeAnchorExpiry(receiptRecord) != nil {
				state.quarantined = true
			}
		}
		if state.Candidate != nil && receipt.InstanceOCID != state.Candidate.InstanceOCID {
			return SlotState{}, fmt.Errorf("%w: receipt identifies a different instance than the candidate pin", ErrRecordAuthorization)
		}
		if state.Result != nil && validatePeerReceiptForResult(receipt, *state.Result) != nil {
			return SlotState{}, ErrRecordAuthorization
		}
	}

	if state.Result != nil {
		if state.Manifest == nil || state.PeerReceipt == nil ||
			validatePeerReceiptForResult(*state.PeerReceipt, *state.Result) != nil {
			return SlotState{}, fmt.Errorf("%w: result lacks its exact manifest and receipt", ErrRecordAuthorization)
		}
		if state.ResultRecord != nil && state.PeerReceiptRecord != nil && state.ManifestRecord != nil {
			if err := validateCompletionWriteOrder(*state.ManifestRecord, *state.PeerReceiptRecord, *state.ResultRecord); err != nil {
				return SlotState{}, err
			}
			if validateResultStoredWithinProofs(*state.ManifestRecord, *state.PeerReceiptRecord, *state.ResultRecord,
				ledger.config.AnchorExpiresAt) != nil {
				state.quarantined = true
			}
		}
		if state.Head.ResultDigest != "" && state.Head.CandidateDigest != state.CandidateRecord.SHA256 {
			return SlotState{}, ErrRecordAuthorization
		}
		// A staged result is not yet durable positive evidence. It can be
		// resumed only while the exact pinned instance observation remains
		// fresh; persisted result-ready and complete states are replayable.
		if state.ResultRecord == nil && validateManagedPeerObservationFreshness(*state.Result, ledger.now().UTC()) != nil {
			state.quarantined = true
		}
	}
	if progressErr == nil && progress.Phase == ManagedPeerProgressReceipt && state.PeerReceiptRecord != nil &&
		progress.PendingProofDigest != state.PeerReceiptRecord.SHA256 {
		if !state.quarantined {
			return SlotState{}, ErrRecordAuthorization
		}
	}
	if progressErr == nil && progress.Phase == ManagedPeerProgressResult && state.ResultRecord != nil &&
		progress.PendingProofDigest != state.ResultRecord.SHA256 {
		if !state.quarantined {
			return SlotState{}, ErrRecordAuthorization
		}
	}
	if state.Candidate == nil && state.Head.CandidateDigest != "" {
		return SlotState{}, ErrRecordAuthorization
	}
	if !allowQuarantine && state.quarantined {
		return SlotState{}, ErrRecordAuthorization
	}
	if state.Progress == nil && state.CandidateRecord != nil {
		// A crash may occur after the immutable candidate PUT and before the
		// first progress CAS. The fixed candidate key is enough to forbid launch.
		return state, nil
	}
	if state.Progress == nil && (state.PeerReceiptRecord != nil || state.ResultRecord != nil) {
		state.quarantined = true
	}
	return state, nil
}

func (verified VerifiedFounderPlan) AuthorizePeerRecovery(
	slot string,
	recovery ManagedPeerRecoveryAuthorization,
	roots trust.Keyring,
	now time.Time,
	selectorExpiresAt time.Time,
	policy trust.Policy,
) (VerifiedFounderPeer, error) {
	if !verified.verified || !recovery.verified || !validFounderNow(now) || !validFounderNow(selectorExpiresAt) {
		return VerifiedFounderPeer{}, ErrFounderPeerAuthorization
	}
	serverDate := recovery.ServerDate()
	authorizationTime := recovery.AuthorizationTime()
	if serverDate.IsZero() || authorizationTime.IsZero() {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: recovery token has no trusted OCI clock", ErrFounderPeerAuthorization)
	}
	// The OCI Date header is a conservative lower bound for checking not-before
	// times. The final successful read plus one-second header precision and
	// monotonic elapsed time is the conservative upper bound for expiry checks.
	// Never let a stale caller-supplied time move either bound backward.
	if now.After(authorizationTime) {
		authorizationTime = now
	}
	if !selectorExpiresAt.After(authorizationTime) {
		return VerifiedFounderPeer{}, ErrFounderPlanExpired
	}
	lowerBoundPlan, err := VerifyFounderPlan(verified.wire, roots, verified.anchorWire, verified.manifestWires, serverDate, policy)
	if err != nil {
		return VerifiedFounderPeer{}, err
	}
	current, err := VerifyFounderPlan(verified.wire, roots, verified.anchorWire, verified.manifestWires, authorizationTime, policy)
	if err != nil {
		return VerifiedFounderPeer{}, err
	}
	if current.digest != lowerBoundPlan.digest || current.anchor.Digest() != lowerBoundPlan.anchor.Digest() {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: root-authorized founder proof changed between trusted clock bounds", ErrFounderPeerAuthorization)
	}
	return authorizeFounderPeerRecovery(current.snapshot(), slot, recovery, authorizationTime, selectorExpiresAt)
}

func authorizeFounderPeerRecovery(current founderPlanSnapshot, slot string, recovery ManagedPeerRecoveryAuthorization, authorizationTime, selectorExpiresAt time.Time) (VerifiedFounderPeer, error) {
	index := slices.IndexFunc(current.plan.Peers, func(row FounderPeerRow) bool { return row.Slot == slot })
	if index < 0 {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: slot %q is not a planned peer", ErrFounderPeerAuthorization, slot)
	}
	row := current.plan.Peers[index]
	rowDigest, err := FounderPeerRowDigest(row)
	if err != nil {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: hash peer row: %v", ErrFounderPeerAuthorization, err)
	}
	state := recovery.state
	intent := state.Intent
	if recovery.scope != (BootstrapScope{DeploymentID: current.plan.DeploymentID, Cell: string(current.plan.Cell), Slot: slot}) ||
		intent.Mode != IntentModeManaged || intent.SchemaVersion != 1 || state.Head.SchemaVersion != 1 || intent.Attempt != state.Head.Attempt ||
		intent.Generation != state.Head.Generation || state.IntentRecord.SHA256 != state.Head.IntentDigest ||
		objectDigest(state.IntentRecord.Bytes) != state.IntentRecord.SHA256 ||
		state.Head.ResultDigest != "" && recovery.phase != ManagedPeerRecoveryComplete && recovery.phase != ManagedPeerRecoveryQuarantined ||
		state.Head.ResultDigest == "" && recovery.phase == ManagedPeerRecoveryComplete ||
		intent.FounderPlanSHA256 != current.digest || intent.PeerRowDigest != rowDigest ||
		intent.ManifestDigest != row.ManifestSHA256 || intent.ImageOCID != row.ImageOCID ||
		!sameProfile(launchProfileForIntent(intent), LaunchProfile{
			Slot: row.Slot, CompartmentOCID: row.CompartmentOCID, AvailabilityDomain: row.AvailabilityDomain,
			FaultDomain: row.FaultDomain, SubnetOCID: row.SubnetOCID,
			NetworkSecurityGroupOCIDs: row.NetworkSecurityGroupOCIDs, Shape: row.Shape,
		}) || recovery.serverDate.IsZero() {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: recovery state does not pin this exact founder plan row", ErrFounderPeerAuthorization)
	}
	manifest := current.manifests[slot]
	if manifest.Digest() != row.ManifestSHA256 {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: selected manifest digest differs from its founder row", ErrFounderPeerAuthorization)
	}
	if state.ManifestRecord != nil && (state.Manifest == nil || state.ManifestRecord.SHA256 != row.ManifestSHA256 ||
		objectDigest(state.ManifestRecord.Bytes) != state.ManifestRecord.SHA256) {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: persisted manifest differs from the selected founder row", ErrFounderPeerAuthorization)
	}
	if state.PeerReceiptRecord != nil && (state.PeerReceipt == nil ||
		state.PeerReceiptRecord.SHA256 == "" || objectDigest(state.PeerReceiptRecord.Bytes) != state.PeerReceiptRecord.SHA256 ||
		validatePeerReceiptForIntent(*state.PeerReceipt, intent, state.IntentRecord.SHA256) != nil) {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: persisted peer receipt differs from the current intent", ErrFounderPeerAuthorization)
	}
	if state.ResultRecord != nil && (state.Result == nil || state.PeerReceiptRecord == nil ||
		objectDigest(state.ResultRecord.Bytes) != state.ResultRecord.SHA256 ||
		validateResultForIntent(*state.Result, intent, state.IntentRecord.SHA256) != nil ||
		state.Result.PeerReceiptDigest != state.PeerReceiptRecord.SHA256) {
		return VerifiedFounderPeer{}, fmt.Errorf("%w: persisted result differs from the current intent and receipt", ErrFounderPeerAuthorization)
	}
	if state.CandidateRecord != nil {
		if state.Candidate == nil || state.CandidateRecord.SHA256 == "" ||
			objectDigest(state.CandidateRecord.Bytes) != state.CandidateRecord.SHA256 ||
			validateManagedPeerCandidateForIntent(*state.Candidate, intent, state.IntentRecord.SHA256,
				current.digest, rowDigest, row.ManifestSHA256) != nil {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: persisted candidate differs from the exact current intent and founder row", ErrFounderPeerAuthorization)
		}
	}
	if state.ProgressRecord != nil {
		if state.Progress == nil || state.ProgressRecord.SHA256 == "" ||
			objectDigest(state.ProgressRecord.Bytes) != state.ProgressRecord.SHA256 || state.CandidateRecord == nil ||
			state.Progress.CandidateDigest != state.CandidateRecord.SHA256 ||
			state.Progress.Attempt != intent.Attempt || state.Progress.Generation != intent.Generation {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: persisted progress does not bind the verified candidate and current intent", ErrFounderPeerAuthorization)
		}
	}
	switch recovery.phase {
	case ManagedPeerRecoveryClean:
		if state.ManifestRecord != nil || state.PeerReceiptRecord != nil || state.ResultRecord != nil || state.CandidateRecord != nil ||
			state.ProgressRecord != nil || state.Head.ResultDigest != "" || state.Head.CandidateDigest != "" {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: clean recovery phase contains durable peer proofs", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryManifestOnly:
		if state.ManifestRecord == nil || state.PeerReceiptRecord != nil || state.ResultRecord != nil || state.CandidateRecord != nil ||
			state.ProgressRecord != nil || state.Head.ResultDigest != "" || state.Head.CandidateDigest != "" {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: manifest-only recovery phase has inconsistent records", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryCandidateOnly:
		if state.CandidateRecord == nil || state.PeerReceiptRecord != nil || state.ResultRecord != nil || state.Head.ResultDigest != "" ||
			state.Progress != nil && state.Progress.Phase != ManagedPeerProgressCandidate {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: candidate-only recovery phase has inconsistent records", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryProofStaged:
		if state.CandidateRecord == nil || state.ProgressRecord == nil || state.Progress == nil ||
			state.Progress.Phase != ManagedPeerProgressReceipt && state.Progress.Phase != ManagedPeerProgressResult {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: proof-staged recovery phase has inconsistent progress", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryQuarantined:
		if state.CandidateRecord == nil && state.PeerReceipt == nil && state.Result == nil {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: quarantined recovery state has no persisted instance identity", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryReceiptOnly:
		if state.ManifestRecord == nil || state.PeerReceiptRecord == nil || state.CandidateRecord == nil ||
			state.ResultRecord != nil || state.Head.ResultDigest != "" {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: receipt-only recovery phase has inconsistent records", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryResultReady:
		if state.ManifestRecord == nil || state.PeerReceiptRecord == nil || state.CandidateRecord == nil ||
			state.ResultRecord == nil || state.Head.ResultDigest != "" {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: result-ready recovery phase has inconsistent records", ErrFounderPeerAuthorization)
		}
	case ManagedPeerRecoveryComplete:
		if state.ManifestRecord == nil || state.PeerReceiptRecord == nil || state.CandidateRecord == nil || state.ResultRecord == nil ||
			state.Head.ResultDigest != state.ResultRecord.SHA256 || state.Head.CandidateDigest != state.CandidateRecord.SHA256 {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: complete recovery phase has inconsistent records", ErrFounderPeerAuthorization)
		}
	default:
		return VerifiedFounderPeer{}, fmt.Errorf("%w: recovery phase is malformed", ErrFounderPeerAuthorization)
	}
	deadline := earlierTime(current.plan.LaunchDeadline, current.expiresAt,
		current.anchorExpiresAt, manifest.ExpiresAt(), selectorExpiresAt)
	if recovery.phase == ManagedPeerRecoveryClean || recovery.phase == ManagedPeerRecoveryManifestOnly {
		intentEnvelope, decodeErr := trust.DecodeEnvelope(state.IntentRecord.Bytes)
		if decodeErr != nil || !intentEnvelope.ExpiresAt.After(authorizationTime) {
			return VerifiedFounderPeer{}, ErrFounderPlanExpired
		}
		if err := CheckRetryWindow(StoredRecord{
			LastModified: state.IntentRecord.LastModified,
			ServerDate:   authorizationTime,
		}); err != nil {
			return VerifiedFounderPeer{}, fmt.Errorf("%w: original intent retry window is not current: %v", ErrFounderPlanExpired, err)
		}
		deadline = earlierTime(deadline, intentEnvelope.ExpiresAt, state.IntentRecord.LastModified.Add(maxRetryAge))
	}
	if !authorizationTime.Before(deadline) {
		return VerifiedFounderPeer{}, ErrFounderPlanExpired
	}
	launch := LaunchAuthorization{
		scope: recovery.scope, intent: intent, intentRecord: cloneStoredRecord(state.IntentRecord),
		head: state.Head, headRecord: cloneStoredRecord(state.HeadRecord),
	}
	recoveryCopy := recovery
	recoveryCopy.state = cloneSlotState(state)
	return VerifiedFounderPeer{
		row: cloneFounderPeerRow(row), manifest: manifest, manifestWire: bytes.Clone(current.manifestWires[slot]), launch: launch,
		recovery: &recoveryCopy, planDigest: current.digest, rowDigest: rowDigest,
		effectDeadline: deadline, verified: true,
	}, nil
}

func (verified VerifiedFounderPeer) LaunchRequest(now time.Time) (FounderPeerLaunchRequest, error) {
	if !verified.verified || !validFounderNow(now) {
		return FounderPeerLaunchRequest{}, ErrFounderPeerAuthorization
	}
	if verified.recovery != nil {
		authorizationTime := verified.recovery.AuthorizationTime()
		if authorizationTime.IsZero() {
			return FounderPeerLaunchRequest{}, ErrFounderPeerAuthorization
		}
		if now.Before(authorizationTime) {
			now = authorizationTime
		}
	}
	if !verified.launch.intentRecord.ServerDate.IsZero() && now.Before(verified.launch.intentRecord.ServerDate) {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: request time predates the OCI launch read", ErrFounderPeerAuthorization)
	}
	if verified.recovery != nil && now.Before(verified.recovery.serverDate.Add(time.Second)) {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: request time predates the final OCI recovery read", ErrFounderPeerAuthorization)
	}
	if !now.Before(verified.effectDeadline) {
		return FounderPeerLaunchRequest{}, ErrFounderPlanExpired
	}
	if verified.recovery != nil && verified.recovery.phase != ManagedPeerRecoveryClean &&
		verified.recovery.phase != ManagedPeerRecoveryManifestOnly {
		return FounderPeerLaunchRequest{}, fmt.Errorf("%w: recovery phase %q does not authorize an OCI launch", ErrFounderPeerAuthorization, verified.recovery.phase)
	}
	return verified.launchRequest(), nil
}

func (verified VerifiedFounderPeer) launchRequest() FounderPeerLaunchRequest {
	intent := verified.launch.intent
	return FounderPeerLaunchRequest{
		StartupAuthority: verified.manifest,
		DeploymentID:     intent.DeploymentID, Cell: oci.Region(intent.Cell), Environment: intent.Environment,
		Slot: intent.Slot, Node: intent.Node, Attempt: intent.Attempt, Generation: intent.Generation,
		IntentSHA256: verified.launch.intentRecord.SHA256, FounderPlanSHA256: verified.planDigest,
		PeerRowSHA256: verified.rowDigest, ManifestSHA256: verified.row.ManifestSHA256,
		ManifestWire: bytes.Clone(verified.manifestWire),
		CreateKey:    intent.CreateKey, RetryToken: intent.RetryToken, HeadETag: verified.launch.headRecord.ETag,
		Row: cloneFounderPeerRow(verified.row),
	}
}

// ObservationRequest authorizes observing only the exact instance already
// named by a persisted, verified peer receipt. Other recovery phases have no
// observation-only capability.
func (verified VerifiedFounderPeer) ObservationRequest(now time.Time) (FounderPeerObservationRequest, error) {
	if !verified.verified || verified.recovery == nil ||
		verified.recovery.phase != ManagedPeerRecoveryReceiptOnly &&
			verified.recovery.phase != ManagedPeerRecoveryCandidateOnly &&
			verified.recovery.phase != ManagedPeerRecoveryProofStaged &&
			verified.recovery.phase != ManagedPeerRecoveryQuarantined || !validFounderNow(now) {
		return FounderPeerObservationRequest{}, ErrFounderPeerAuthorization
	}
	authorizationTime := verified.recovery.AuthorizationTime()
	if authorizationTime.IsZero() {
		return FounderPeerObservationRequest{}, ErrFounderPeerAuthorization
	}
	if now.Before(authorizationTime) {
		now = authorizationTime
	}
	if now.Before(verified.recovery.serverDate.Add(time.Second)) {
		return FounderPeerObservationRequest{}, fmt.Errorf("%w: request time predates the OCI recovery read", ErrFounderPeerAuthorization)
	}
	if !now.Before(verified.effectDeadline) {
		return FounderPeerObservationRequest{}, ErrFounderPlanExpired
	}
	state := verified.recovery.state
	instanceOCID := ""
	if state.Candidate != nil {
		instanceOCID = state.Candidate.InstanceOCID
	} else if state.PeerReceipt != nil {
		instanceOCID = state.PeerReceipt.InstanceOCID
	} else if state.Result != nil {
		instanceOCID = state.Result.InstanceOCID
	}
	if !isOCID(instanceOCID, "instance") {
		return FounderPeerObservationRequest{}, fmt.Errorf("%w: recovery state has no verified instance identity", ErrFounderPeerAuthorization)
	}
	return FounderPeerObservationRequest{
		Launch: verified.launchRequest(), InstanceOCID: instanceOCID,
	}, nil
}

func testLedgerSDKPrivateKey(t *testing.T) string {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	data := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	return string(data)
}

type countingTLSConfigProvider struct {
	calls   int
	changed bool
}

func (provider *countingTLSConfigProvider) NewOrDefault() (*tls.Config, error) {
	provider.calls++
	return &tls.Config{MinVersion: tls.VersionTLS12}, nil
}

func (provider *countingTLSConfigProvider) WatchedFilesModified() bool {
	return provider.changed
}

func invalidLedgerPrefixConfig(config LedgerConfig) LedgerConfig {
	config.Prefix = "../invalid"
	return config
}

func ledgerConfigForRegion(t *testing.T, fixture *ledgerFixture, region oci.Region) LedgerConfig {
	t.Helper()
	config := fixture.ledger.config
	config.Cell = region
	ociRegion, err := region.OCIRegion()
	if err != nil {
		t.Fatal(err)
	}
	config.KMSKeyID = "ocid1.key.oc1." + ociRegion + ".ledger"
	config.HeadKMSKeyID = "ocid1.key.oc1." + ociRegion + ".head"
	publicWire, err := trust.EncodeDelegatedPublicKey(fixture.authority.peerPublic)
	if err != nil {
		t.Fatal(err)
	}
	capabilities := make([]trust.Capability, 0, 3)
	for _, domain := range []string{domainBootstrapHead, domainBootstrapIntent, domainBootstrapResult,
		domainBootstrapCandidate, domainBootstrapProgress} {
		capabilities = append(capabilities, trust.Capability{
			Domain: domain, DeploymentID: config.DeploymentID, Cell: string(region), Environment: config.Environment,
			Role: roleController, Slots: slices.Clone(config.ControllerSlots), Actions: []string{"sign"},
		})
	}
	delegation, err := trust.SignDelegation(trust.Delegation{
		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID(t, fixture.authority.peerPublic),
		SubjectPublicKey: publicWire, Capabilities: capabilities,
	}, fixture.now, fixture.now.Add(fixture.maxLifetime), fixture.authority.rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	verified, err := trust.VerifyDelegationCurrent(delegation, config.TrustRoots, fixture.now, config.TrustPolicy)
	if err != nil {
		t.Fatal(err)
	}
	config.Delegations = []trust.VerifiedDelegation{verified}
	return config
}

func NewInstancePrincipalLedgerWithProvider(region oci.Region, config LedgerConfig, provider common.ConfigurationProvider) (*Ledger, error) {
	return newInstancePrincipalLedgerWithProviderMode(region, config, provider, false)
}

func NewInstancePrincipalSDKHTTPClient() (*http.Client, error) {
	return newInstancePrincipalHTTPClient(nil)
}

func newInstancePrincipalLedger(
	region oci.Region,
	config LedgerConfig,
	newProvider instancePrincipalProviderFactory,
) (*Ledger, error) {
	provider, err := newInstancePrincipalConfigurationProvider(region, config, newProvider)
	if err != nil {
		return nil, err
	}
	return newInstancePrincipalLedgerWithProviderMode(region, config, provider, false)
}

func newInstancePrincipalLedgerWithProviderMode(
	region oci.Region,
	config LedgerConfig,
	provider common.ConfigurationProvider,
	historical bool,
) (*Ledger, error) {
	ociRegion, err := validateInstancePrincipalLedgerScope(region, config)
	if err != nil {
		return nil, err
	}
	if provider == nil {
		return nil, errors.New("bootstrap ledger OCI configuration provider is nil")
	}
	providerRegion, err := provider.Region()
	if err != nil {
		return nil, fmt.Errorf("read bootstrap ledger OCI provider region: %w", err)
	}
	if providerRegion != ociRegion {
		return nil, fmt.Errorf("bootstrap ledger OCI provider region %q does not match anchored region %q", providerRegion, ociRegion)
	}
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(provider)
	if err != nil {
		return nil, fmt.Errorf("create OCI Object Storage client for bootstrap ledger: %w", err)
	}
	client.SetRegion(ociRegion)
	client.HTTPClient, err = NewInstancePrincipalSDKHTTPClient()
	if err != nil {
		return nil, fmt.Errorf("configure OCI Object Storage HTTP transport: %w", err)
	}
	if historical {
		return NewHistoricalLedger(&client, config)
	}
	return NewLedger(&client, config)
}

func newInstancePrincipalConfigurationProvider(
	region oci.Region,
	config LedgerConfig,
	newProvider instancePrincipalProviderFactory,
) (common.ConfigurationProvider, error) {
	ociRegion, err := validateInstancePrincipalLedgerScope(region, config)
	if err != nil {
		return nil, err
	}
	if newProvider == nil {
		return nil, errors.New("bootstrap ledger Instance Principal provider factory is nil")
	}

	provider, err := newProvider(common.Region(ociRegion), BoundInstancePrincipalDispatcher)
	if err != nil {
		return nil, fmt.Errorf("create OCI Instance Principal provider for bootstrap ledger: %w", err)
	}
	if provider == nil {
		return nil, errors.New("create OCI Instance Principal provider for bootstrap ledger: provider is nil")
	}
	return provider, nil
}

func validateInstancePrincipalLedgerScope(region oci.Region, config LedgerConfig) (string, error) {
	ociRegion, err := region.OCIRegion()
	if err != nil {
		return "", err
	}
	if err := validateInstancePrincipalLedgerConfig(config); err != nil {
		return "", err
	}
	if config.Cell != region {
		return "", fmt.Errorf("bootstrap ledger cell %q does not match requested OCI region %q", config.Cell, region)
	}
	if err := validateInstancePrincipalSDKOverrides(); err != nil {
		return "", err
	}
	return ociRegion, nil
}

func validateInstancePrincipalSDKOverrides() error {
	for _, name := range []string{
		metadataBaseURLEnv,
		authClientRegionURLEnv,
		customCertBundleEnv,
		customClientCertEnv,
		customClientKeyEnv,
	} {
		if _, overridden := os.LookupEnv(name); overridden {
			return fmt.Errorf("bootstrap ledger does not allow OCI SDK override %s", name)
		}
	}
	return nil
}

func validateInstancePrincipalLedgerConfig(config LedgerConfig) error {
	// Keep this pre-authentication check aligned with NewLedger's config check.
	// NewLedger remains authoritative after the SDK client is constructed.
	if validateLedgerAnchor(config) != nil || !ledgerIDPattern.MatchString(config.Namespace) ||
		!ledgerNamePattern.MatchString(config.Bucket) || !strings.HasPrefix(config.KMSKeyID, "ocid1.key.") ||
		len(config.KMSKeyID) > 255 || strings.ContainsAny(config.KMSKeyID, " \t\r\n") || !validLedgerPrefix(config.Prefix) ||
		!ledgerNamePattern.MatchString(config.HeadBucket) || config.HeadBucket == config.Bucket ||
		!strings.HasPrefix(config.HeadKMSKeyID, "ocid1.key.") || len(config.HeadKMSKeyID) > 255 ||
		strings.ContainsAny(config.HeadKMSKeyID, " \t\r\n") || !ledgerIDPattern.MatchString(config.Environment) ||
		config.TrustPolicy.MaxLifetime <= 0 || config.TrustPolicy.ClockSkew < 0 ||
		len(config.ControllerSlots) == 0 || len(config.ControllerSlots) > 64 || hasDuplicate(config.ControllerSlots) ||
		len(config.TrustRoots) == 0 && len(config.Delegations) == 0 || validateLedgerDelegations(config) != nil {
		return errors.New("bootstrap ledger configuration is invalid before Instance Principal setup")
	}
	for _, slot := range config.ControllerSlots {
		if !controllerSlotRE.MatchString(slot) {
			return errors.New("bootstrap ledger configuration has an invalid anchor-pinned controller slot set")
		}
	}
	return nil
}

func BoundInstancePrincipalDispatcher(dispatcher common.HTTPRequestDispatcher) (common.HTTPRequestDispatcher, error) {
	client, ok := dispatcher.(*http.Client)
	if !ok || client == nil {
		return nil, errors.New("OCI Instance Principal SDK supplied an unsupported HTTP dispatcher")
	}
	return newInstancePrincipalHTTPClient(client)
}

func newInstancePrincipalHTTPClient(source *http.Client) (*http.Client, error) {
	var client http.Client
	if source != nil {
		client = *source
	}
	defaultTransport, ok := http.DefaultTransport.(*http.Transport)
	if !ok {
		return nil, errors.New("OCI SDK default HTTP transport has an unsupported type")
	}
	var transport http.RoundTripper = defaultTransport.Clone()
	if source != nil && source.Transport != nil {
		switch provided := source.Transport.(type) {
		case *http.Transport:
			transport = provided.Clone()
		case *common.OciHTTPTransportWrapper:
			if provided == nil || provided.TLSConfigProvider == nil {
				return nil, errors.New("OCI SDK supplied an incomplete HTTP transport wrapper")
			}
			transport = &common.OciHTTPTransportWrapper{
				RefreshRate:       provided.RefreshRate,
				TLSConfigProvider: provided.TLSConfigProvider,
				TransportTemplate: noProxyOCITransportTemplate(provided.TransportTemplate),
			}
		default:
			return nil, errors.New("OCI SDK supplied an unsupported HTTP transport")
		}
	}
	if pinned, ok := transport.(*http.Transport); ok {
		pinned.Proxy = nil
	}
	client.Transport = transport
	client.Timeout = instancePrincipalRequestTimeout
	client.CheckRedirect = func(*http.Request, []*http.Request) error {
		return errors.New("OCI Instance Principal HTTP redirects are not permitted")
	}
	return &client, nil
}

func noProxyOCITransportTemplate(template common.TransportTemplateProvider) common.TransportTemplateProvider {
	return func(tlsConfig *tls.Config) (http.RoundTripper, error) {
		provided, err := template.NewOrDefault(tlsConfig)
		if err != nil {
			return nil, err
		}
		transport, ok := provided.(*http.Transport)
		if !ok || transport == nil {
			return nil, errors.New("OCI SDK supplied an unsupported HTTP transport template")
		}
		pinned := transport.Clone()
		pinned.Proxy = nil
		return pinned, nil
	}
}

func (t *OciHTTPTransportWrapper) RoundTrip(req *http.Request) (*http.Response, error) {
	delegate, err := t.refreshDelegate(false /* force */)
	if err != nil {
		return nil, err
	}

	return delegate.RoundTrip(req)
}

// Refresh forces refresh of the underlying delegate.
func (t *OciHTTPTransportWrapper) Refresh(force bool) error {
	_, err := t.refreshDelegate(force)
	return err
}

// Delegate returns the currently active http.RoundTripper.
// Might be nil.
func (t *OciHTTPTransportWrapper) Delegate() http.RoundTripper {
	t.mux.RLock()
	defer t.mux.RUnlock()

	return t.delegate
}

// refreshDelegate refreshes the delegate (and its TLS config) if:
//   - force is true
//   - it's been more than RefreshRate since the last time the client was refreshed.
func (t *OciHTTPTransportWrapper) refreshDelegate(force bool) (http.RoundTripper, error) {
	// read-lock first, since it's cheaper than write lock
	t.mux.RLock()
	if !t.shouldRefreshLocked(force) {
		delegate := t.delegate
		t.mux.RUnlock()

		return delegate, nil
	}

	// upgrade to write-lock, and we'll need to check again for the same condition as above
	// to avoid multiple initializations by multiple "refresher" goroutines
	t.mux.RUnlock()
	t.mux.Lock()
	defer t.mux.Unlock()
	if !t.shouldRefreshLocked(force) {
		return t.delegate, nil
	}

	// For this check we need the delegate to be set once before we check for change in cert files
	if t.delegate != nil && !t.TLSConfigProvider.WatchedFilesModified() {
		Debug("No modification in custom certs or ca bundle skipping refresh")
		// Updating the last refresh time to make sure the next check is only done after the refresh interval has passed
		t.lastRefreshedAt = time.Now()
		return t.delegate, nil
	}

	Logf("Loading tls config from TLSConfigProvider")
	tlsConfig, err := t.TLSConfigProvider.NewOrDefault()
	if err != nil {
		return nil, fmt.Errorf("refreshing tls.Config from template: %w", err)
	}

	t.delegate, err = t.TransportTemplate.NewOrDefault(tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("refreshing http.RoundTripper from template: %w", err)
	}

	t.lastRefreshedAt = time.Now()
	return t.delegate, nil
}

// shouldRefreshLocked returns whether the client (and its TLS config)
// needs to be refreshed.
func (t *OciHTTPTransportWrapper) shouldRefreshLocked(force bool) bool {
	if force || t.delegate == nil {
		return true
	}
	return t.refreshRate() > 0 && time.Since(t.lastRefreshedAt) > t.refreshRate()
}

func (t *OciHTTPTransportWrapper) refreshRate() time.Duration {
	return t.RefreshRate
}

func (t TransportTemplateProvider) NewOrDefault(tlsClientConfig *tls.Config) (http.RoundTripper, error) {
	if t == nil {
		return DefaultTransport(tlsClientConfig)
	}
	return t(tlsClientConfig)
}

// DefaultTransport creates a clone of http.DefaultTransport
// and applies the tlsClientConfig on top of it.
// The result is never nil, to prevent panics in client code.
// Never returns any errors, but needs to return an error
// to adhere to TransportTemplate interface.
func DefaultTransport(tlsClientConfig *tls.Config) (*http.Transport, error) {
	transport := CloneHTTPDefaultTransport()
	if isExpectHeaderDisabled := IsEnvVarFalse(UsingExpectHeaderEnvVar); !isExpectHeaderDisabled {
		transport.Proxy = http.ProxyFromEnvironment
		transport.DialContext = (&net.Dialer{
			Timeout:   30 * time.Second,
			KeepAlive: 30 * time.Second,
			DualStack: true,
		}).DialContext
		transport.ForceAttemptHTTP2 = true
		transport.MaxIdleConns = 100
		transport.IdleConnTimeout = 90 * time.Second
		transport.TLSHandshakeTimeout = 10 * time.Second
		transport.ExpectContinueTimeout = 3 * time.Second
	}
	transport.TLSClientConfig = tlsClientConfig
	return transport, nil
}

// CloneHTTPDefaultTransport returns a clone of http.DefaultTransport.
func CloneHTTPDefaultTransport() *http.Transport {
	return http.DefaultTransport.(*http.Transport).Clone()
}
